/// Generated from `avatar.shapes`: original Memoshi silhouettes in a 100-unit view box.
public enum AvatarShape: String, CaseIterable, Sendable {
  /// Canonical `avatar.shapes.arch` silhouette.
  case arch
  /// Canonical `avatar.shapes.bean` silhouette.
  case bean
  /// Canonical `avatar.shapes.capsule` silhouette.
  case capsule
  /// Canonical `avatar.shapes.circle` silhouette.
  case circle
  /// Canonical `avatar.shapes.cloud` silhouette.
  case cloud
  /// Canonical `avatar.shapes.drop` silhouette.
  case drop
  /// Canonical `avatar.shapes.flower` silhouette.
  case flower
  /// Canonical `avatar.shapes.hexagon` silhouette.
  case hexagon
  /// Canonical `avatar.shapes.leaf` silhouette.
  case leaf
  /// Canonical `avatar.shapes.shield` silhouette.
  case shield
  /// Canonical `avatar.shapes.squircle` silhouette.
  case squircle
  /// Canonical `avatar.shapes.star` silhouette.
  case star

  /// The parametric outline in view-box units, y down.
  var outline: AvatarOutline {
    switch self {
    case .arch:
      AvatarOutline.arch(rect: CGRect(x: 10, y: 5, width: 80, height: 90), bottomCornerRadius: 11)
    case .bean:
      AvatarOutline.dentedEllipse(
        center: CGPoint(x: 50, y: 54),
        semiAxes: CGSize(width: 45, height: 33),
        dentDepth: 9,
        dentAngle: -90,
        dentWidthRad: 0.55,
        rotation: -10
      )
    case .capsule:
      AvatarOutline.stadium(center: CGPoint(x: 50, y: 50), size: CGSize(width: 66, height: 90))
    case .circle: AvatarOutline.circle(center: CGPoint(x: 50, y: 50), radius: 44)
    case .cloud:
      AvatarOutline.union(
        circles: [AvatarCircle(31, 56, 19), AvatarCircle(55, 41, 25), AvatarCircle(77, 58, 15)],
        roundedRect: CGRect(x: 8, y: 52, width: 84, height: 34),
        roundedRectCornerRadius: 17
      )
    case .drop:
      AvatarOutline.teardrop(
        circleCenter: CGPoint(x: 50, y: 62),
        radius: 33,
        apex: CGPoint(x: 50, y: 5),
        apexCornerRadius: 4
      )
    case .flower:
      AvatarOutline.radialWave(
        center: CGPoint(x: 50, y: 50),
        baseRadius: 40,
        amplitude: 5.5,
        lobes: 6,
        phase: -90
      )
    case .hexagon:
      AvatarOutline.roundedPolygon(
        center: CGPoint(x: 50, y: 50),
        sides: 6,
        circumradius: 47,
        startAngle: -90,
        cornerRadius: 8
      )
    case .leaf:
      AvatarOutline.lens(
        center: CGPoint(x: 50, y: 50),
        length: 98,
        width: 62,
        rotation: -45,
        tipCornerRadius: 6
      )
    case .shield:
      AvatarOutline.shield(
        top: 8,
        left: 10,
        right: 90,
        shoulderY: 46,
        tip: CGPoint(x: 50, y: 95),
        sideControls: [CGPoint(x: 88, y: 78), CGPoint(x: 12, y: 78)],
        cornerRadius: 10
      )
    case .squircle:
      AvatarOutline.superellipse(
        center: CGPoint(x: 50, y: 50),
        semiAxes: CGSize(width: 43, height: 43),
        exponent: 4.5
      )
    case .star:
      AvatarOutline.roundedStar(
        center: CGPoint(x: 50, y: 54),
        points: 5,
        outerRadius: 48,
        innerRatio: 0.62,
        startAngle: -90,
        cornerRadius: 7
      )
    }
  }

  /// Where the shared eye mark sits on this silhouette.
  var eyes: AvatarEyeLine {
    switch self {
    case .arch: AvatarEyeLine(lineY: 50, spread: 24, scale: 1)
    case .bean: AvatarEyeLine(lineY: 56, spread: 24, scale: 0.95)
    case .capsule: AvatarEyeLine(lineY: 40, spread: 22, scale: 0.95)
    case .circle: AvatarEyeLine(lineY: 47, spread: 24, scale: 1)
    case .cloud: AvatarEyeLine(lineY: 63, spread: 23, scale: 0.95)
    case .drop: AvatarEyeLine(lineY: 63, spread: 23, scale: 0.95)
    case .flower: AvatarEyeLine(lineY: 49, spread: 23, scale: 0.95)
    case .hexagon: AvatarEyeLine(lineY: 48, spread: 24, scale: 1)
    case .leaf: AvatarEyeLine(lineY: 50, spread: 22, scale: 0.9)
    case .shield: AvatarEyeLine(lineY: 42, spread: 24, scale: 1)
    case .squircle: AvatarEyeLine(lineY: 47, spread: 24, scale: 1)
    case .star: AvatarEyeLine(lineY: 55, spread: 19, scale: 0.8)
    }
  }
}

