/// Generated from `avatar.sizes`, smallest first.
public enum AvatarSize: String, CaseIterable, Sendable {
  /// Canonical `avatar.sizes.xs` (16 pt).
  case xs
  /// Canonical `avatar.sizes.sm` (20 pt).
  case sm
  /// Canonical `avatar.sizes.md` (28 pt).
  case md
  /// Canonical `avatar.sizes.lg` (40 pt).
  case lg
  /// Canonical `avatar.sizes.xl` (64 pt).
  case xl
  /// Canonical `avatar.sizes.xxl` (96 pt).
  case xxl

  /// The canonical point dimension.
  public var points: CGFloat {
    switch self {
    case .xs: 16
    case .sm: 20
    case .md: 28
    case .lg: 40
    case .xl: 64
    case .xxl: 96
    }
  }

  /// Whether status and unread badges render at this size.
  public var showsBadges: Bool {
    switch self {
    case .xs: false
    case .sm: false
    case .md: true
    case .lg: true
    case .xl: true
    case .xxl: true
    }
  }

  /// The loop frame-rate cap; zero means this size never loops.
  var loopFrameRateMax: Float {
    switch self {
    case .xs: 0
    case .sm: 30
    case .md: 30
    case .lg: 60
    case .xl: 60
    case .xxl: 60
    }
  }
}

/// Generated from `avatar.face.poses`: poses of the eye mark every bot shares.
public enum AvatarEyePose: String, CaseIterable, Sendable {
  /// Canonical `avatar.face.poses.blink` eye pose.
  case blink
  /// Canonical `avatar.face.poses.closed` eye pose.
  case closed
  /// Canonical `avatar.face.poses.half` eye pose.
  case half
  /// Canonical `avatar.face.poses.lookLeading` eye pose.
  case lookLeading
  /// Canonical `avatar.face.poses.lookTrailing` eye pose.
  case lookTrailing
  /// Canonical `avatar.face.poses.open` eye pose.
  case open
  /// Canonical `avatar.face.poses.squint` eye pose.
  case squint
  /// Canonical `avatar.face.poses.wide` eye pose.
  case wide

  /// Eye scale and offset in view-box units.
  var transform: AvatarEyeTransform {
    switch self {
    case .blink: AvatarEyeTransform(scaleX: 1, scaleY: 0.1, offsetX: 0, offsetY: 0)
    case .closed: AvatarEyeTransform(scaleX: 1, scaleY: 0.15, offsetX: 0, offsetY: 1.5)
    case .half: AvatarEyeTransform(scaleX: 1, scaleY: 0.5, offsetX: 0, offsetY: 1.5)
    case .lookLeading: AvatarEyeTransform(scaleX: 1, scaleY: 1, offsetX: -6.5, offsetY: 0)
    case .lookTrailing: AvatarEyeTransform(scaleX: 1, scaleY: 1, offsetX: 6.5, offsetY: 0)
    case .open: AvatarEyeTransform(scaleX: 1, scaleY: 1, offsetX: 0, offsetY: 0)
    case .squint: AvatarEyeTransform(scaleX: 1, scaleY: 0.75, offsetX: 0, offsetY: 0)
    case .wide: AvatarEyeTransform(scaleX: 1.15, scaleY: 1.15, offsetX: 0, offsetY: 0)
    }
  }
}
